imal(16, 4) // 实际金额\n  money     Decimal @db.Decimal(16, 4) // 实收金额\n  cost      Decimal @db.Decimal(16, 4) // 单据费用\n  account   Int?    @default(0) // 结算账户\n  people    Int?    @default(0) // 关联人员\n  logistics String? @db.Text // 物流信息\n  file      String? @db.Text // 单据附件\n  data      String? @default(\"\") @db.VarChar(256) // 备注信息\n  more      String? @db.Text // 扩展信息\n  examine   Boolean // 审核状态\n  nucleus   Boolean // 核销状态\n  cse       Boolean // 费用状态\n  invoice   Boolean // 发票状态\n  check     Boolean // 核对状态\n  user      Int // 制单人\n\n  @@map(\"is_sell\")\n}\n\nmodel SellInfo {\n  id        Int     @id @default(autoincrement())\n  pid       Int // 所属单据\n  source    Int?    @default(0) // 关联单据|SOR_INFO\n  goods     Int // 所属商品\n  attr      String? @default(\"\") @db.VarChar(64) // 辅助属性\n  unit      String? @default(\"\") @db.VarChar(32) // 商品单位\n  warehouse Int?    @default(0) // 所属仓库\n  batch     String? @default(\"\") @db.VarChar(64) // 批次号\n  mfd       String? @default(\"\") @db.VarChar(32) // 生产日期\n  price     Decimal @db.Decimal(12, 4) // 单价\n  nums      Decimal @db.Decimal(12, 4) // 数量\n  serial    String? @db.Text // 序列号\n  retreat   Decimal @default(0.0000) @db.Decimal(12, 4) // 退货数量\n  discount  Decimal @default(0.00) @db.Decimal(5, 2) // 折扣率\n  dsc       Decimal @default(0.0000) @db.Decimal(16, 4) // 折扣额\n  total     Decimal @db.Decimal(16, 4) // 金额\n  tax       Decimal @default(0.00) @db.Decimal(5, 2) // 税率\n  tat       Decimal @default(0.0000) @db.Decimal(16, 4) // 税额\n  tpt       Decimal @db.Decimal(16, 4) // 价税合计\n  data      String? @default(\"\") @db.VarChar(256) // 备注信息\n\n  @@map(\"is_sell_info\")\n}\n\nmodel Imy {\n  id       Int     @id @default(autoincrement())\n  frame    Int // 所属组织\n  customer Int // 客户\n  time     Int // 单据时间\n  number   String  @db.VarChar(32) // 单据编号\n  total    Decimal @db.Decimal(16, 4) // 单据金额\n  people   Int?    @default(0) // 关联人员\n  file     String? @db.Text // 单据附件\n  data     String? @default(\"\") @db.VarChar(2